#!/usr/bin/env python3
"""Render benchmarks/results.json into benchmarks/results.md (markdown table)."""
import json
from pathlib import Path

here = Path(__file__).resolve().parent
r = json.loads((here / "results.json").read_text())

lines = [
    "# ClearVoice benchmark results (measured, not estimated)",
    "",
    f"Core: `{r['core_version']}`, 48 kHz mono, RNNoise pinned at `70f1d25`.",
    "Test signals: synthetic pseudo-speech + noise (fan/keyboard/babble/traffic/hum),",
    "generated by `make_test_signals.py` (deterministic seeds). Run on this machine;",
    "see `run_eval.py` / `measure_latency.py` to reproduce.",
    "",
    "## Speech-in-noise (SNR of denoised output vs clean reference; higher = better)",
    "",
    "| mix | input SNR (dB) | RNNoise SNR (dB) | Δ | RNNoise SI-SDR (dB) | clipping |",
    "|---|---|---|---|---|---|",
]
for name, e in sorted(r["mixes"].items()):
    rn = e["rnnoise"]
    delta = rn["snr_db"] - e["input_snr_db"]
    lines.append(
        f"| {name} | {e['input_snr_db']:.2f} | {rn['snr_db']:.2f} | {delta:+.2f} | {rn['si_sdr_db']:.2f} | {rn['clipping']} |"
    )
lines += [
    "",
    "## Noise-only reduction (10*log10(rms_in²/rms_out²); higher = more noise removed)",
    "",
    "| noise | input RMS | reduction (dB) | clipping |",
    "|---|---|---|---|",
]
for name, e in sorted(r["noise_only"].items()):
    lines.append(f"| {name} | {e['in_rms']:.3f} | {e['noise_reduction_db']:.2f} | {e['clipping']} |")
lines += [
    "",
    "## Notes (honest interpretation)",
    "",
    "- Stationary low-frequency noise (fan, traffic, AC-like) is suppressed strongly (~19–23 dB SNR gain).",
    "- Babble (speech-like) is deliberately preserved — that is the intended voice-protection behavior.",
    "- Mains hum (50 Hz) mostly passes RNNoise's high-pass by design; keyboard transients are kept.",
    "- Clipping counts on 0 dB mixes come from the synthetic mix itself saturating int16, not from the engine.",
    "- VB-CABLE end-to-end loopback latency: UNVERIFIED (driver not installed in this environment).",
]
(here / "results.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
print("wrote benchmarks/results.md")
